import json, urllib.request
url = 'https://www.tikwm.com/api/comment/list/?url=https://www.tiktok.com/@tonyle.hcm/photo/7641442941860482324&count=30'
data = json.loads(urllib.request.urlopen(url).read())
if data.get('code') == 0:
    for c in data.get('data',{}).get('comments',[]):
        print(f'- {c.get(\"user\",{}).get(\"nickname\",\"?\")}: {c.get(\"text\",\"\")}')
else:
    print('No comments or error')
